package com.aistock.prediction.verification;
import java.time.*;import java.util.*;import com.aistock.common.BusinessException;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class VerificationDueMysqlTest {
 final VerificationMysqlTest d=new VerificationMysqlTest();
 VerificationDueRepository repo(Clock clock){return new VerificationDueRepository(d.f.jdbc,VerificationMysqlTest.MAPPER,clock,20);}
 @Test void dueIncludesHiddenHistoryAndExcludesFutureFailedAndCurrentComplete(){var due=d.forecast("SUCCEEDED",true);var complete=d.forecast("SUCCEEDED",false);d.forecast("FAILED",false);var future=d.forecast("SUCCEEDED",false);var snap=(com.fasterxml.jackson.databind.node.ObjectNode)d.snapshot();((com.fasterxml.jackson.databind.node.ObjectNode)snap.path("prediction").path("points").get(0)).put("targetDate","2026-10-08");d.f.jdbc.update("update forecast_request set snapshot_json=? where prediction_id=?",snap.toString(),future.toString());String vid=UUID.randomUUID().toString();d.f.jdbc.update("insert into forecast_verification_version(version_id,prediction_id,realization_version_id,rule_version,due_through,content_hash,evidence_json,evaluation_json,created_at) values(?,?,?,?,?,'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','{}','{\"verifiedCount\":5}',?)",vid,complete.toString(),UUID.randomUUID().toString(),VerificationRecords.RULE,VerificationMysqlTest.TARGETS.get(0),java.sql.Timestamp.from(VerificationMysqlTest.NOW.instant()));d.f.jdbc.update("insert into forecast_verification_head(prediction_id,current_version_id,due_through) values(?,?,?)",complete.toString(),vid,VerificationMysqlTest.TARGETS.get(0));var page=repo(VerificationMysqlTest.NOW).due(VerificationMysqlTest.TARGETS.get(1),null,50);assertEquals(1,page.items().size());assertEquals(due,page.items().get(0).predictionId());assertEquals(VerificationRecords.RULE,page.items().get(0).ruleVersion());assertNull(page.nextCursor());}
 @Test void keysetLimitsAndCapAreBounded(){for(int i=0;i<4;i++)d.forecast("SUCCEEDED",false);var q=repo(Clock.fixed(Instant.parse("2027-01-01T14:00:00Z"),ZoneOffset.UTC));var a=q.due(LocalDate.parse("2027-01-01"),null,2);var b=q.due(LocalDate.parse("2027-01-01"),a.nextCursor(),2);assertEquals(2,a.items().size());assertEquals(2,b.items().size());assertNull(b.nextCursor());assertTrue(a.items().get(1).predictionId().toString().compareTo(b.items().get(0).predictionId().toString())<0);assertEquals(VerificationMysqlTest.ORIGIN.plusDays(90),a.items().get(0).dueThrough());assertThrows(BusinessException.class,()->q.due(LocalDate.parse("2027-01-02"),null,50));assertThrows(BusinessException.class,()->q.due(LocalDate.parse("2027-01-01"),null,51));}
 @Test void beforeTwentyUsesYesterdayAndFirstTargetNotDueIsEmpty(){var id=d.forecast("SUCCEEDED",false);var clock=Clock.fixed(Instant.parse("2026-09-22T03:00:00Z"),ZoneOffset.UTC);var q=repo(clock);assertTrue(q.due(VerificationMysqlTest.ORIGIN,null,50).items().isEmpty());assertThrows(BusinessException.class,()->q.due(VerificationMysqlTest.TARGETS.get(0),null,50));assertEquals(0,d.f.jdbc.queryForObject("select count(*) from forecast_verification_version",Integer.class));}
}
